"""Provided: checks on how your team is built. Do not edit this file.

These read your agents; they make no calls to the model.
"""

from run import agents_in, is_agent_tool, own_tools
from team import build_single, build_team


def test_the_team_has_three_agents_with_roles() -> None:
    """At least three agents, each with its own name and written role."""
    agents = agents_in(build_team())
    names = [agent.name for agent in agents]
    assert len(set(names)) >= 3, names
    for agent in agents:
        assert isinstance(agent.instructions, str), agent.name
        assert len(agent.instructions.split()) >= 10, agent.name


def test_the_lead_reaches_the_others() -> None:
    """The lead connects through handoffs, agent tools, or both."""
    lead = build_team()
    assert lead.handoffs or any(is_agent_tool(t) for t in lead.tools)


def test_the_team_has_two_tools_of_its_own() -> None:
    """Two or more tools that are not other agents."""
    assert len(own_tools(build_team())) >= 2


def test_the_single_agent_works_alone_with_the_same_tools() -> None:
    """No handoffs, no agent tools, and each of the team's own tools."""
    single = build_single()
    assert not single.handoffs
    assert not any(is_agent_tool(t) for t in single.tools)
    assert set(own_tools(build_team())) <= {t.name for t in single.tools}
